#!/usr/bin/env python3
"""Regenerate src/main/viewerArt.ts from the SVG assets used by the viewer page."""
import os
os.chdir(os.path.join(os.path.dirname(__file__), '..'))
gwen = open('src/renderer/src/assets/faces/spider-gwen.svg').read().strip()
spidey = open('src/renderer/src/assets/spidey.svg').read().strip()
out = (
    "// Generated by build/gen-viewer-art.py — inlined SVG art for the viewer page.\n"
    "// Regenerate after changing spider-gwen.svg or spidey.svg.\n\n"
    "export const GWEN_SVG = `" + gwen.replace('`', '\\`') + "`\n\n"
    "export const SPIDEY_SVG = `" + spidey.replace('`', '\\`') + "`\n"
)
open('src/main/viewerArt.ts', 'w').write(out)
print('wrote src/main/viewerArt.ts')
